an>    </dd>          <dt><span class="parameter" style="color:#3A95FF">baseUrl</span></dt>    <dd>     <span class="simpara">      When a <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> is passed, <span class="parameter" style="color:#3A95FF">uri</span> is applied on      <span class="parameter" style="color:#3A95FF">baseUrl</span>, if <span class="parameter" style="color:#3A95FF">uri</span> is a relative reference.      If either <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> is passed, or <span class="parameter" style="color:#3A95FF">uri</span> is a not a relative reference, then      <span class="parameter" style="color:#3A95FF">baseUrl</span> doesn't have any effect.     </span>    </dd>     </dl> </div> <div class="refsect1 errors" id="refsect1-uri-rfc3986-uri.construct-errors">  <h3 class="title">错误／异常</h3>    <p class="simpara">   If the resulting URI is invalid, a <span class="exceptionname"><a href="https://php.net/manual/zh/class.uri-invaliduriexception.php" class="exceptionname">Uri\InvalidUriException</a></span> is thrown.  </p> </div> <div class="refsect1 seealso" id="refsect1-uri-rfc3986-uri.construct-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Uri\Rfc3986\Uri::parse()} - Parse a URI</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Uri\Rfc3986\Uri::resolve()} - Resolve a URI with the current object as the base URL</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Uri\WhatWg\Url::__construct()} - Construct the Url object</span></li>  </ul> </div></div>
 */
        public function __construct(string $uri, ?\Uri\Rfc3986\Uri $baseUrl = null) {}

/**
 * <div id="uri-rfc3986-uri.getscheme" class="refentry"> <div class="refnamediv">  <h1 class="refname">Uri\Rfc3986\Uri::getScheme</h1>  <p class="verinfo">(PHP 8 &gt;= 8.5.0)</p><p class="refpurpose"><span class="refname">Uri\Rfc3986\Uri::getScheme</span> — <span class="dc-title">Retrieve the normalized scheme component</span></p> </div> <div class="refsect1 description" id="refsect1-uri-rfc3986-uri.getscheme-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Uri\Rfc3986\Uri::getScheme</strong></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span></div>  <p class="simpara">   Retrieves the normalized scheme component.  </p> </div> <div class="refsect1 parameters" id="refsect1-uri-rfc3986-uri.getscheme-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-uri-rfc3986-uri.getscheme-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the normalized scheme component as a <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> if the scheme component exists, <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> is returned otherwise.  </p> </div> <div class="refsect1 examples" id="refsect1-uri-rfc3986-uri.getscheme-examples">  <h3 class="title">示例</h3>  <div class="example" id="uri-rfc3986-uri.getscheme.example.basic">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>Uri\Rfc3986\Uri::getScheme()</strong></span> basic example</strong></p>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$uri </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Uri\Rfc3986\Uri</span><span style="color: #007700">(</span><span style="color: #DD0000">"https://example.com"</span><span style="color: #007700">);<br><br>echo </span><span style="color: #9876AA">\$uri</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getScheme</span><span style="color: #007700">();<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">https</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-uri-rfc3986-uri.getscheme-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Uri\Rfc3986\Uri::getRawScheme()} - Retrieve the raw scheme component</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Uri\Rfc3986\Uri::withScheme()} - Modify the scheme component</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Uri\WhatWg\Url::getScheme()} - Retrieve the scheme component</span></li>  </ul> </div></div>
