/**
 * <div id="uri-rfc3986-uri.equals" class="refentry"> <div class="refnamediv">  <h1 class="refname">Uri\Rfc3986\Uri::equals</h1>  <p class="verinfo">(PHP 8 &gt;= 8.5.0)</p><p class="refpurpose"><span class="refname">Uri\Rfc3986\Uri::equals</span> — <span class="dc-title">Check if two URIs are equivalent</span></p> </div> <div class="refsect1 description" id="refsect1-uri-rfc3986-uri.equals-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Uri\Rfc3986\Uri::equals</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.uri-rfc3986-uri.php" class="type Uri\Rfc3986\Uri" style="color:#EAB766">Uri\Rfc3986\Uri</a></span> <span class="parameter" style="color:#3A95FF">\$uri</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/enum.uri-uricomparisonmode.php" class="type Uri\UriComparisonMode" style="color:#EAB766">Uri\UriComparisonMode</a></span> <span class="parameter" style="color:#3A95FF">\$comparisonMode</span><span class="initializer"> = <strong><span>Uri\UriComparisonMode::ExcludeFragment</span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="simpara">   Checks if two URIs are equivalent.  </p> </div> <div class="refsect1 parameters" id="refsect1-uri-rfc3986-uri.equals-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">uri</span></dt>    <dd>     <span class="simpara">      URI to compare the current URI against.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">comparisonMode</span></dt>    <dd>     <span class="simpara">      Whether the frag