round:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$uri </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Uri\Rfc3986\Uri</span><span style="color: #007700">(</span><span style="color: #DD0000">"https://example.com/foo/bar?baz"</span><span style="color: #007700">);<br><br>echo </span><span style="color: #9876AA">\$uri</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">toString</span><span style="color: #007700">();<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">https://example.com/foo/bar?baz</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-uri-rfc3986-uri.tostring-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Uri\Rfc3986\Uri::toRawString()} - Recompose the raw URI</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Uri\WhatWg\Url::toAsciiString()} - Recompose the URL as an ASCII string</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Uri\WhatWg\Url::toUnicodeString()} - Recompose the URL as a Unicode string</span></li>  </ul> </div></div>
 */
        public function toString(): string {}

/**
 * <div id="uri-rfc3986-uri.torawstring" class="refentry"> <div class="refnamediv">  <h1 class="refname">Uri\Rfc3986\Uri::toRawString</h1>  <p class="verinfo">(PHP 8 &gt;= 8.5.0)</p><p class="refpurpose"><span class="refname">Uri\Rfc3986\Uri::toRawString</span> — <span class="dc-title">Recompose the raw URI</span></p> </div> <div class="refsect1 description" id="refsect1-uri-rfc3986-uri.torawstring-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Uri\Rfc3986\Uri::toRawString</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>  <p class="simpara">   Recomposes the raw (non-normalized) URI to a <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-uri-rfc3986-uri.torawstring-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-uri-rfc3986-uri.torawstring-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the recomposed raw (non-normalized) URI as a <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>.  </p> </div> <div class="refsect1 examples" id="refsect1-uri-rfc3986-uri.torawstring-examples">  <h3 class="title">示例</h3>  <div class="example" id="uri-rfc3986-uri.torawstring.example.basic">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>Uri\Rfc3986\Uri::toRawString()</strong></span> basic example</strong></p>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$uri </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Uri\Rfc3986\Uri</span><span style="color: #007700">(</span><span style="color: #DD0000">"https://example.com/foo/bar?baz"</span><span style="color: #007700">);<br><br>echo </span><span style="color: #9876AA">\$uri</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">toRawString</span><span style="color: #007700">();<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">https://example.com/foo/bar?baz</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-uri-rfc3986-uri.torawstring-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Uri\Rfc3986\Uri::toString()} - Recompose the normalized URI</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Uri\WhatWg\Url::toAsciiString()} - Recompose the URL as an ASCII string</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Uri\WhatWg\Url::toUnicodeString()} - Recompose the URL as a Unicode string</span></li>  </ul> </div></div>
 */
        public function toRawString(): string {}

/**
 * <div id="uri-rfc3986-uri.resolve" class="refentry"> <div class="refnamediv">  <h1 class="refname">Uri\Rfc3986\Uri::resolve</h1>  <p class="verinfo">(PHP 8 &gt;= 8.5.0)</p><p class="refpurpose"><span class="refname">Uri\Rfc3986\Uri::resolve</span> — <span class="dc-title">Resolve a URI with the current object as the base URL</span></p> </div> <div class="refsect1 description" id="refsect1-uri-rfc3986-uri.resolve-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Uri\Rfc3986\Uri::resolve</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$uri</span></span>): <span class="type" style="color:#EAB766">static</span></div>  <p class="simpara">   Resolves a URI - which may potentially be a relative reference - with the current object as the base URL.  </p> </div> <div class="refsect1 parameters" id="refsect1-uri-rfc3986-uri.resolve-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">uri</span></dt>    <dd>     <span class="simpara">      A URI to apply on the current object.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-uri-rfc3986-uri.resolve-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   A new <span class="classname"><a href="https://php.net/manual/zh/class.uri-rfc3986-uri.php" class="classname">Uri\Rfc3986\Uri</a></span> instance.  </p> </div> <div class="refsect1 errors" id="refsect1-uri-rfc3986-uri.resolve-errors">  <h3 class="title">错误／异常</h3>    <p class="simpara">   If the resulting URI is invalid, a <span class="exceptionname"><a href="https://php.net/manual/zh/class.uri-invaliduriexception.php" class="exceptionname">Uri\InvalidUriException</a></span> is thrown.  </p> </div> <div class="refsect1 examples" id="refsect1-uri-rfc3986-uri.resolve-examples">  <h3 class="title">示例</h3>  <div class="example" id="uri-rfc3986-uri.resolve.example.basic">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>Uri\Rfc3986\Uri::resolve()</strong></span> basic example</strong></p>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$uri </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Uri\Rfc3986\Uri</span><span style="color: #007700">(</span><span style="color: #DD0000">"https://example.com"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$uri </span><span style="color: #007700">= </span><span style="color: #9876AA">\$uri</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">resolve</span><span style="color: #007700">(</span><span style="color: #DD0000">"/foo"</span><span style="color: #007700">);<br><br>echo </span><span style="color: #9876AA">\$uri</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">toRawString</span><span style="color: #007700">();<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">https://example.com/foo</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-uri-rfc3986-uri.resolve-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Uri\Rfc3986\Uri::__construct()} - Construct the Uri object</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Uri\Rfc3986\Uri::parse()} - Parse a URI</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Uri\WhatWg\Url::resolve()} - Resolve a URL with the current object as the base URL</span></li>  </ul> </div></div>
 */
        public function resolve(string $uri): static {}

