/**
 * <div id="uri-rfc3986-uri.unserialize" class="refentry"> <div class="refnamediv">  <h1 class="refname">Uri\Rfc3986\Uri::__unserialize</h1>  <p class="verinfo">(PHP 8 &gt;= 8.5.0)</p><p class="refpurpose"><span class="refname">Uri\Rfc3986\Uri::__unserialize</span> — <span class="dc-title">Deserialize the data parameter into a Uri object</span></p> </div> <div class="refsect1 description" id="refsect1-uri-rfc3986-uri.unserialize-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Uri\Rfc3986\Uri::__unserialize</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$data</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Deserializes a data parameter into a <span class="classname"><a href="https://php.net/manual/zh/class.uri-rfc3986-uri.php" class="classname">Uri\Rfc3986\Uri</a></span> object.  </p> </div> <div class="refsect1 parameters" id="refsect1-uri-rfc3986-uri.unserialize-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">data</span></dt>    <dd>     <span class="simpara">      The serialized data as an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-uri-rfc3986-uri.unserialize-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-uri-rfc3986-uri.unserialize-errors">  <h3 class="title">错误／异常</h3>  <p class="simpara">   If the <span class="methodname" style="color:#CC7832"><strong>__unserialize()</strong></span> method is called on an already existing URI, <span class="exceptionname"><a href="https://php.net/manual/zh/class.error.php" class="exceptionname">Error</a></span>   is thrown.  </p>    <p class="simpara">   If the resulting URI is invalid, a <span class="exceptionname"><a href="https://php.net/manual/zh/class.uri-invaliduriexception.php" class="exceptionname">Uri\InvalidUriException</a></span> is thrown.  </p> </div> <div class="refsect1 seealso" id="refsect1-uri-rfc3986-uri.unserialize-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Uri\Rfc3986\Uri::__serialize()} - Serialize the Uri object</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Uri\WhatWg\Url::__unserialize()} - Deserialize the data parameter into a Url object</span></li>  </ul> </div></div>
 */
        public function __unserialize(array $data): void {}

/**
 * <div id="uri-rfc3986-uri.debuginfo" class="refentry"> <div class="refnamediv">  <h1 class="refname">Uri\Rfc3986\Uri::__debugInfo</h1>  <p class="verinfo">(PHP 8 &gt;= 8.5.0)</p><p class="refpurpose"><span class="refname">Uri\Rfc3986\Uri::__debugInfo</span> — <span class="dc-title">Return the internal state of the URI</span></p> </div> <div class="refsect1 description" id="refsect1-uri-rfc3986-uri.debuginfo-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Uri\Rfc3986\Uri::__debugInfo</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>  <p class="simpara">   Returns the internal state of the URI.  </p> </div> <div class="refsect1 parameters" id="refsect1-uri-rfc3986-uri.debuginfo-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-uri-rfc3986-uri.debuginfo-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the internal state of the URI as an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>.  </p> </div> <div class="refsect1 seealso" id="refsect1-uri-rfc3986-uri.debuginfo-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Uri\WhatWg\Url::__debugInfo()} - Return the internal state of the URL</span></li>  </ul> </div></div>
 */
        public function __debugInfo(): array {}

        /**
         * @since 8.6
         */
        public function getHostType(): ?UriHostType {}

        /**
         * @since 8.6
         */
        public function getUriType(): ?UriType {}
    }

    /**
     * @since 8.6
     */
    enum UriHostType implements \UnitEnum
    {
        case RegName;
        case Ipv4;
        case Ipv6;
        case IpvFuture;
    }

    /**
     * @since 8.6
     */
    enum UriType implements \UnitEnum
    {
        case Absolute;
        case Relative;
    }

    /**
     * @since 8.6
     */
    final class UriBuilder
    {
        private ?string $scheme;
        private ?string $userinfo;
        private ?string $host;
        private ?int $port;
        private string $path;
        private ?string $query;
        private ?string $fragment;


        public function reset(): static {}


        public function setScheme(?string $scheme): static {}


        public function setUserInfo(?string $userInfo): static {}


        public function setHost(?string $host): static {}


        public function setPort(?int $port): static {}


        public function setPath(string $path): static {}


        public function setQuery(?string $query): static {}


        public function setFragment(?string $fragment): static {}


        public function build(?Uri $baseUrl = null): Uri {}
    }
}

namespace Uri\WhatWg {
