ulting URL is invalid, a <span class="exceptionname"><a href="https://php.net/manual/zh/class.uri-whatwg-invalidurlexception.php" class="exceptionname">Uri\WhatWg\InvalidUrlException</a></span> is thrown.  </p> </div> <div class="refsect1 examples" id="refsect1-uri-whatwg-url.withquery-examples">  <h3 class="title">示例</h3>  <div class="example" id="uri-whatwg-url.withquery.example.basic">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>Uri\WhatWg\Url::withQuery()</strong></span> basic example</strong></p>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$url </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Uri\WhatWg\Url</span><span style="color: #007700">(</span><span style="color: #DD0000">"https://example.com?foo=bar"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$url </span><span style="color: #007700">= </span><span style="color: #9876AA">\$url</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">withQuery</span><span style="color: #007700">(</span><span style="color: #DD0000">"foo=baz"</span><span style="color: #007700">);<br><br>echo </span><span style="color: #9876AA">\$url</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getQuery</span><span style="color: #007700">();<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">foo=baz</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-uri-whatwg-url.withquery-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Uri\WhatWg\Url::getQuery()} - Retrieve the query component</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Uri\Rfc3986\Uri::withQuery()} - Modify the query component</span></li>  </ul> </div></div>
 */
        public function withQuery(?string $query): static {}

