/**
 * <div id="uri-whatwg-url.equals" class="refentry"> <div class="refnamediv">  <h1 class="refname">Uri\WhatWg\Url::equals</h1>  <p class="verinfo">(PHP 8 &gt;= 8.5.0)</p><p class="refpurpose"><span class="refname">Uri\WhatWg\Url::equals</span> — <span class="dc-title">Check if two URLs are equivalent</span></p> </div> <div class="refsect1 description" id="refsect1-uri-whatwg-url.equals-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Uri\WhatWg\Url::equals</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.uri-whatwg-url.php" class="type Uri\WhatWg\Url" style="color:#EAB766">Uri\WhatWg\Url</a></span> <span class="parameter" style="color:#3A95FF">\$url</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/enum.uri-uricomparisonmode.php" class="type Uri\UriComparisonMode" style="color:#EAB766">Uri\UriComparisonMode</a></span> <span class="parameter" style="color:#3A95FF">\$comparisonMode</span><span class="initializer"> = <strong><span>Uri\UriComparisonMode::ExcludeFragment</span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="simpara">   Checks if two URLs are equivalent.  </p> </div> <div class="refsect1 parameters" id="refsect1-uri-whatwg-url.equals-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">url</span></dt>    <dd>     <span class="simpara">      URL to compare the current URL against.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">comparisonMode</span></dt>    <dd>     <span class="simpara">      Whether the fragment component is taken into account of the comparison      (<span class="literal">Uri\UriComparisonMode::IncludeFragment</span>) or not      (<span class="literal">Uri\UriComparisonMode::ExcludeFragment</span>). By default, the fragment is excluded.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-uri-whatwg-url.equals-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if the two URLs are equivalent, or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> otherwise.  </p> </div> <div class="refsect1 examples" id="refsect1-uri-whatwg-url.equals-examples">  <h3 class="title">示例</h3>  <div class="example" id="uri-whatwg-url.equals.example.basic">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>Uri\WhatWg\Url::equals()</strong></span> basic example</strong></p>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$url1 </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Uri\WhatWg\Url</span><span style="color: #007700">(</span><span style="color: #DD0000">"https://example.com"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$url2 </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Uri\WhatWg\Url</span><span style="color: #007700">(</span><span style="color: #DD0000">"HTTPS://example.com"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$url1</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">equals</span><span style="color: #007700">(</span><span style="color: #9876AA">\$url2</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">bool(true)</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-uri-whatwg-url.equals-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Uri\Rfc3986\Uri::equals()} - Check if two URIs are equivalent</span></li>  </ul> </div></div>
 */
        public function equals(\Uri\WhatWg\Url $url, \Uri\UriComparisonMode $comparisonMode = \Uri\UriComparisonMode::ExcludeFragment): bool {}

/**
 * <div id="uri-whatwg-url.toasciistring" class="refentry"> <div class="refnamediv">  <h1 class="refname">Uri\WhatWg\Url::toAsciiString</h1>  <p class="verinfo">(PHP 8 &gt;= 8.5.0)</p><p class="refpurpose"><span class="refname">Uri\WhatWg\Url::toAsciiString</span> — <span class="dc-title">Recompose the URL as an ASCII <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span></p> </div> <div class="refsect1 description" id="refsect1-uri-whatwg-url.toasciistring-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Uri\WhatWg\Url::toAsciiString</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>  <p class="simpara">   Recomposes the URL as an ASCII <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>, using punycode transcription instead of Unicode characters in the   host component.  </p> </div> <div class="refsect1 parameters" id="refsect1-uri-whatwg-url.toasciistring-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-uri-whatwg-url.toasciistring-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the recomposed URL as an ASCII <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>.  </p> </div> <div class="refsect1 examples" id="refsect1-uri-whatwg-url.toasciistring-examples">  <h3 class="title">示例</h3>  <div class="example" id="uri-whatwg-url.toasciistring.example.basic">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>Uri\WhatWg\Url::toAsciiString()</strong></span> basic example</strong></p>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$url </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Uri\WhatWg\Url</span><span style="color: #007700">(</span><span style="color: #DD0000">"https://example.com/foo/bar?baz"</span><span style="color: #007700">);<br><br>echo </span><span style="color: #9876AA">\$url</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">toAsciiString</span><span style="color: #007700">();<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">https://example.com/foo/bar?baz</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-uri-whatwg-url.toasciistring-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Uri\WhatWg\Url::toUnicodeString()} - Recompose the URL as a Unicode string</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Uri\Rfc3986\Uri::toRawString()} - Recompose the raw URI</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Uri\Rfc3986\Uri::toString()} - Recompose the normalized URI</span></li>  </ul> </div></div>
 */
        public function toAsciiString(): string {}

/**
 * <div id="uri-whatwg-url.tounicodestring" class="refentry"> <div class="refnamediv">  <h1 class="refname">Uri\WhatWg\Url::toUnicodeString</h1>  <p class="verinfo">(PHP 8 &gt;= 8.5.0)</p><p class="refpurpose"><span class="refname">Uri\WhatWg\Url::toUnicodeString</span> — <span class="dc-title">Recompose the URL as a Unicode <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span></p> </div> <div class="refsect1 description" id="refsect1-uri-whatwg-url.tounicodestring-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Uri\WhatWg\Url::toUnicodeString</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>  <p class="simpara">   Recomposes the URL as a <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>, where the host component may contain Unicode characters.  </p> </div> <div class="refsect1 parameters" id="refsect1-uri-whatwg-url.tounicodestring-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-uri-whatwg-url.tounicodestring-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the recomposed URL as a Unicode <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>.  </p> </div> <div class="refsect1 examples" id="refsect1-uri-whatwg-url.tounicodestring-examples">  <h3 class="title">示例</h3>  <div class="example" id="uri-whatwg-url.tounicodestring.example.basic">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>Uri\WhatWg\Url::toUnicodeString()</strong></span> basic example</strong></p>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$url </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Uri\WhatWg\Url</span><span style="color: #007700">(</span><span style="color: #DD0000">"https://example.com/foo/bar?baz"</span><span style="color: #007700">);<br><br>echo </span><span style="color: #9876AA">\$url</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">toUnicodeString</span><span style="color: #007700">();<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">https://example.com/foo/bar?baz</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-uri-whatwg-url.tounicodestring-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Uri\WhatWg\Url::toAsciiString()} - Recompose the URL as an ASCII string</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Uri\Rfc3986\Uri::toRawString()} - Recompose the raw URI</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Uri\Rfc3986\Uri::toString()} - Recompose the normalized URI</span></li>  </ul> </div></div>
 */
        public function toUnicodeString(): string {}

        /**
 * <div id="uri-whatwg-url.resolve" class="refentry"> <div class="refnamediv">  <h1 class="refname">Uri\WhatWg\Url::resolve</h1>  <p class="verinfo">(PHP 8 &gt;= 8.5.0)</p><p class="refpurpose"><span class="refname">Uri\WhatWg\Url::resolve</span> — <span class="dc-title">Resolve a URL with the current object as the base URL</span></p> </div> <div class="refsect1 description" id="refsect1-uri-whatwg-url.resolve-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Uri\WhatWg\Url::resolve</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$uri</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter reference" style="color:#3A95FF">&amp;\$softErrors</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766">static</span></div>  <p class="simpara">   Resolves a valid URL string - which may potentially be a relative-URL string - with the current object as the base URL.  </p> </div> <div class="refsect1 parameters" id="refsect1-uri-whatwg-url.resolve-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">uri</span></dt>    <dd>     <span class="simpara">      A valid URL string (e.g. <span class="literal">/foo</span> or (e.g. <span class="literal">https://example.com/foo</span>) to apply on      the current object.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">softErrors</span></dt>    <dd>     <span class="simpara">      An <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> to pass a list of <span class="classname"><a href="https://php.net/manual/zh/class.uri-whatwg-urlvalidationerror.php" class="classname">Uri\WhatWg\UrlValidationError</a></span>      instances by reference to provide extended information about the soft errors triggered during reference resolution.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-uri-whatwg-url.resolve-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   A new <span class="classname"><a href="https://php.net/manual/zh/class.uri-whatwg-url.php" class="classname">Uri\WhatWg\Url</a></span> instance.  </p> </div> <div class="refsect1 errors" id="refsect1-uri-whatwg-url.resolve-errors">  <h3 class="title">错误／异常</h3>    <p class="simpara">   If the resulting URL is invalid, a <span class="exceptionname"><a href="https://php.net/manual/zh/class.uri-whatwg-invalidurlexception.php" class="exceptionname">Uri\WhatWg\InvalidUrlException</a></span> is thrown.  </p> </div> <div class="refsect1 examples" id="refsect1-uri-whatwg-url.resolve-examples">  <h3 class="title">示例</h3>  <div class="example" id="uri-whatwg-url.resolve.example.basic">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>Uri\WhatWg\Url::resolve()</strong></span> basic example</strong></p>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$url </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Uri\WhatWg\Url</span><span style="color: #007700">(</span><span style="color: #DD0000">"https://example.com"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$url </span><span style="color: #007700">= </span><span style="color: #9876AA">\$url</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">resolve</span><span style="color: #007700">(</span><span style="color: #DD0000">"/foo"</span><span style="color: #007700">);<br><br>echo </span><span style="color: #9876AA">\$url</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">toAsciiString</span><span style="color: #007700">();<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">https://example.com/foo</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-uri-whatwg-url.resolve-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Uri\WhatWg\Url::__construct()} - Construct the Url object</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Uri\WhatWg\Url::parse()} - Parse a URL</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Uri\Rfc3986\Uri::resolve()} - Resolve a URI with the current object as the base URL</span></li>  </ul> </div></div>
 * 
         * @param array $softErrors
         *
         * @throws \Uri\WhatWg\InvalidUrlException
         */
        public function resolve(string $uri, &$softErrors = null): static {}

/**
 * <div id="uri-whatwg-url.serialize" class="refentry"> <div class="refnamediv">  <h1 class="refname">Uri\WhatWg\Url::__serialize</h1>  <p class="verinfo">(PHP 8 &gt;= 8.5.0)</p><p class="refpurpose"><span class="refname">Uri\WhatWg\Url::__serialize</span> — <span class="dc-title">Serialize the Url object</span></p> </div> <div class="refsect1 description" id="refsect1-uri-whatwg-url.serialize-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Uri\WhatWg\Url::__serialize</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>  <p class="simpara">   Serializes the <span class="classname"><a href="https://php.net/manual/zh/class.uri-whatwg-url.php" class="classname">Uri\WhatWg\Url</a></span> object.  </p> </div> <div class="refsect1 parameters" id="refsect1-uri-whatwg-url.serialize-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-uri-whatwg-url.serialize-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the serialized URL as an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>.  </p> </div> <div class="refsect1 seealso" id="refsect1-uri-whatwg-url.serialize-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Uri\WhatWg\Url::__unserialize()} - Deserialize the data parameter into a Url object</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Uri\Rfc3986\Uri::__serialize()} - Serialize the Uri object</span></li>  </ul> </div></div>
 */
        public function __serialize(): array {}

/**
 * <div id="uri-whatwg-url.unserialize" class="refentry"> <div class="refnamediv">  <h1 class="refname">Uri\WhatWg\Url::__unserialize</h1>  <p class="verinfo">(PHP 8 &gt;= 8.5.0)</p><p class="refpurpose"><span class="refname">Uri\WhatWg\Url::__unserialize</span> — <span class="dc-title">Deserialize the data parameter into a Url object</span></p> </div> <div class="refsect1 description" id="refsect1-uri-whatwg-url.unserialize-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Uri\WhatWg\Url::__unserialize</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$data</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Deserializes a data parameter into a <span class="classname"><a href="https://php.net/manual/zh/class.uri-whatwg-url.php" class="classname">Uri\WhatWg\Url</a></span> object.  </p> </div> <div class="refsect1 parameters" id="refsect1-uri-whatwg-url.unserialize-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">data</span></dt>    <dd>     <span class="simpara">      The serialized data as an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-uri-whatwg-url.unserialize-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-uri-whatwg-url.unserialize-errors">  <h3 class="title">错误／异常</h3>  <p class="simpara">   If the <span class="methodname" style="color:#CC7832"><strong>__unserialize()</strong></span> method is called on an already existing URL, <span class="exceptionname"><a href="https://php.net/manual/zh/class.error.php" class="exceptionname">Error</a></span>   is thrown.  </p>    <p class="simpara">   If the resulting URI is invalid, a <span class="exceptionname"><a href="https://php.net/manual/zh/class.uri-invaliduriexception.php" class="exceptionname">Uri\InvalidUriException</a></span> is thrown.  </p> </div> <div class="refsect1 seealso" id="refsect1-uri-whatwg-url.unserialize-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Uri\WhatWg\Url::__serialize()} - Serialize the Url object</span></li>   <li><span class="methodname" style="color:#CC7832">{@link Uri\Rfc3986\Uri::__unserialize()} - Deserialize the data parameter into a Uri object</span></li>  </ul> </div></div>
 */
